content.solution_code:
class Gear {
    constructor(name, durability) {
        this.name = name;
        this.durability = durability;
    }

    displayStats() {
        return `Name: ${this.name}, Durability: ${this.durability}%`;
    }
}

class Weapon extends Gear {
    constructor(name, durability, damage) {
        super(name, durability);
        this.damage = damage;
    }

    displayStats() {
        return `${super.displayStats()}, Damage: ${this.damage}`;
    }
}

